document.addEventListener("DOMContentLoaded",function(){const t=document.getElementById("trig-form"),e=document.getElementById("trig-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const n=parseFloat(document.getElementById("trig-angle").value)*Math.PI/180,o=Math.sin(n),a=Math.cos(n),d=Math.tan(n);let i;i=Math.abs(d)<1e-12?"∞":1/d,e.innerHTML=`<b>sin:</b> ${o.toFixed(6)}<br><b>cos:</b> ${a.toFixed(6)}<br><b>tan:</b> ${Math.abs(a)<1e-12?"∞":d.toFixed(6)}<br><b>cot:</b> ${"∞"===i?"∞":i.toFixed(6)}`})});